// Validates the request, keys the urls and builds the cache lookup.
//
// The pace is a constant here rather than a caller argument, because it is enforced by
// the fetch node's batching settings, which are fixed configuration. A caller that could
// ask for a rate the node does not honour would be lied to, so the parameter does not
// exist. Change RATE_PER_SECOND and the batching options on "Fetch pages" together.
const SUPABASE_URL = '';        // TODO: https://<project>.supabase.co
const RATE_PER_SECOND = 3;      // must match batchSize on "Fetch pages"
const USER_AGENT = 'n8n-fetch-cache/1.0';
const MAX_URLS = 200;
const DEFAULT_TTL_HOURS = 24;
const DEFAULT_TIMEOUT_MS = 15000;
const MAX_CONTENT = 200000;

if (!SUPABASE_URL) throw new Error('SUPABASE_URL is not configured in "Prepare batch"');

const input = $input.first().json || {};
const urls = Array.isArray(input.urls) ? input.urls : null;
if (!urls) throw new Error('urls must be an array');
if (!urls.length) throw new Error('urls is empty');
if (urls.length > MAX_URLS) throw new Error('urls exceeds the cap of ' + MAX_URLS);

const ttlHours = input.ttl_hours === undefined ? DEFAULT_TTL_HOURS : Number(input.ttl_hours);
if (!Number.isFinite(ttlHours) || ttlHours < 0) throw new Error('ttl_hours must be a number of 0 or more');

const timeoutMs = input.timeout_ms === undefined ? DEFAULT_TIMEOUT_MS : Number(input.timeout_ms);
if (!Number.isFinite(timeoutMs) || timeoutMs < 1000 || timeoutMs > 120000) {
  throw new Error('timeout_ms must be between 1000 and 120000');
}

// The Code node sandbox exposes no hashing at all: no crypto global, and builtin module
// imports are refused. Both were probed against a live instance, not assumed. So the key
// is a base64url encoding of the url itself: longer than a digest, but deterministic and
// collision-free, which is the only property a cache key needs. It stays this way even if
// a future host offers a hash, because switching encodings would change every key at once
// and silently empty the whole cache.
const keyOf = (s) => {
  const bytes = new TextEncoder().encode(s);
  const b64 = typeof Buffer !== 'undefined'
    ? Buffer.from(bytes).toString('base64')
    : btoa(Array.from(bytes, (b) => String.fromCharCode(b)).join(''));
  return b64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
};

const seen = new Set();
const targets = [];
for (const raw of urls) {
  const url = String(raw || '').trim();
  if (!url) throw new Error('urls contains an empty entry');
  if (!/^https?:\/\//i.test(url)) throw new Error('not an http url: ' + url.slice(0, 80));
  if (seen.has(url)) continue;              // the same url twice in one call is one fetch
  seen.add(url);
  targets.push({ url, urlHash: keyOf(url) });
}

const base = SUPABASE_URL.replace(/\/+$/, '');

return [{
  json: {
    targets,
    requested: urls.length,
    unique: targets.length,
    ttlHours,
    timeoutMs,
    userAgent: USER_AGENT,
    ratePerSecond: RATE_PER_SECOND,
    maxContent: MAX_CONTENT,
    // The lookup is an RPC taking the keys in the body, not a url_hash=in.(...) query
    // string. Two hundred keys in a query string is tens of kilobytes of url, which
    // servers and proxies truncate or reject; the body has no such limit.
    cacheUrl: base + '/rest/v1/rpc/page_cache_lookup',
    cacheKeys: targets.map((t) => t.urlHash),
    storeUrl: base + '/rest/v1/page_cache',
  },
}];

// Splits the batch into cache hits and the urls that actually have to be fetched.
// A ttl of 0 means "never serve from cache", which is how a caller forces a refresh
// without needing a second code path.
const state = $('Prepare batch').first().json;

// "Read cache" runs with fullResponse so that an empty cache still yields one item.
// Without it PostgREST's [] would give the node zero items, n8n would skip every node
// downstream, and the caller would get nothing back instead of a full set of misses.
const res = $input.first().json || {};
const rows = Array.isArray(res.body) ? res.body : Array.isArray(res) ? res : [];
const cached = rows.filter((r) => r && r.url_hash);

const byHash = new Map(cached.map((r) => [r.url_hash, r]));
const cutoff = Date.now() - state.ttlHours * 3600 * 1000;

const hits = [];
const pending = [];
for (const t of state.targets) {
  const row = byHash.get(t.urlHash);
  const fresh = row && state.ttlHours > 0 && Date.parse(row.fetched_at) >= cutoff;
  if (fresh) {
    hits.push({ url: t.url, status: row.status, from_cache: true, content: row.content });
  } else {
    pending.push({ url: t.url, urlHash: t.urlHash, attempt: 0 });
  }
}

return [{
  json: {
    ...state,
    hits,
    pending,
    // The accumulator travels with the item through the retry loop. Keeping it in the
    // data rather than in workflow static data means a crashed run leaves nothing behind
    // for the next one to inherit.
    acc: { fetched: [], errors: [] },
    hitCount: hits.length,
    pendingCount: pending.length,
    hasPending: pending.length > 0,
  },
}];

// One item per url still to fetch. The loop re-enters here with a shorter pending list,
// so this is the only place that turns the batch into individual requests.
const state = $input.first().json;
const pending = Array.isArray(state.pending) ? state.pending : [];
if (!pending.length) return [];

return pending.map((t, i) => ({
  json: {
    url: t.url,
    urlHash: t.urlHash,
    attempt: t.attempt || 0,
    timeoutMs: state.timeoutMs,
    userAgent: state.userAgent,
    // Carried on the first item only: the classifier reads it back to continue the
    // accumulation without duplicating it onto every request.
    carry: i === 0 ? { acc: state.acc, hits: state.hits } : undefined,
  },
}));

// Sorts responses into fetched, retryable and permanently failed.
//
// Only 429 and the transient 5xx family are retried. A 404 or a 500 means the server
// answered and the answer will not change by asking again; retrying those is how one
// broken url becomes a hundred wasted requests.
const RETRYABLE = new Set([429, 502, 503, 504]);
const MAX_ATTEMPTS = 3;

const state = $('Split cache hits').first().json;
const requests = $('Fan out misses').all().map((i) => i.json);
const responses = $input.all();

const carry = requests.length && requests[0].carry
  ? requests[0].carry
  : { acc: { fetched: [], errors: [] }, hits: state.hits };

const fetched = [...carry.acc.fetched];
const errors = [...carry.acc.errors];
const pending = [];

for (let i = 0; i < responses.length; i++) {
  const req = requests[i];
  if (!req) continue;
  const res = responses[i].json || {};

  // With neverError and fullResponse the node hands back the status instead of throwing.
  const status = Number(res.statusCode ?? res.status ?? 0);
  const headers = res.headers || {};
  const body = res.body === undefined ? res.data : res.body;
  const attempt = (req.attempt || 0) + 1;

  if (!status) {
    // No response at all: a timeout or a dns failure. Transient enough to retry.
    if (attempt < MAX_ATTEMPTS) {
      pending.push({ url: req.url, urlHash: req.urlHash, attempt, reason: 'no response' });
    } else {
      errors.push({ url: req.url, status: null, error: 'no response after ' + attempt + ' attempts' });
    }
    continue;
  }

  if (status >= 200 && status < 300) {
    const content = typeof body === 'string' ? body : JSON.stringify(body ?? '');
    fetched.push({
      url: req.url,
      urlHash: req.urlHash,
      status,
      content: content.slice(0, state.maxContent),
      content_type: headers['content-type'] || null,
    });
    continue;
  }

  if (RETRYABLE.has(status) && attempt < MAX_ATTEMPTS) {
    // Retry-After is the server telling us the pace. Ignoring it is how a 429 becomes a ban.
    const ra = parseInt(headers['retry-after'], 10);
    pending.push({
      url: req.url, urlHash: req.urlHash, attempt,
      reason: 'status ' + status,
      retryAfter: Number.isFinite(ra) ? ra : null,
    });
    continue;
  }

  errors.push({
    url: req.url,
    status,
    error: RETRYABLE.has(status) ? 'still ' + status + ' after ' + attempt + ' attempts' : 'http ' + status,
  });
}

// The next pause: 2s, then 8s, then 30s. A server that asked for longer via Retry-After
// wins, because it is the one with the rate limiter.
const attemptNow = pending.length ? Math.min(...pending.map((p) => p.attempt)) : 0;
const askedFor = pending.reduce((m, p) => Math.max(m, p.retryAfter || 0), 0);

return [{
  json: {
    ...state,
    hits: carry.hits,
    acc: { fetched, errors },
    pending,
    hasPending: pending.length > 0,
    attemptNow,
    waitSeconds: Math.max(askedFor, attemptNow === 1 ? 2 : attemptNow === 2 ? 8 : 30),
  },
}];

// Builds the one shape callers rely on, out of cache hits plus everything fetched across
// all attempts plus the failures.
const state = $input.first().json;
const fetched = state.acc.fetched;
const errors = state.acc.errors;

const results = [
  ...state.hits,
  ...fetched.map((f) => ({ url: f.url, status: f.status, from_cache: false, content: f.content })),
];

return [{
  json: {
    results,
    errors,
    stats: {
      requested: state.requested,
      unique: state.unique,
      from_cache: state.hits.length,
      fetched: fetched.length,
      failed: errors.length,
      rate_per_second: state.ratePerSecond,
    },
    // Only successful responses are cached. A 404 stored for a day would be served as
    // truth to every caller until it expired.
    rows: fetched.map((f) => ({
      url_hash: f.urlHash,
      url: f.url,
      status: f.status,
      content: f.content,
      content_type: f.content_type,
      fetched_at: new Date().toISOString(),
    })),
    storeUrl: state.storeUrl,
    hasRows: fetched.length > 0,
  },
}];
